def is_palindrome(s):
    cleaned = ''.join(ch.lower() for ch in s if not ch.isspace())
    return cleaned == cleaned[::-1]

def fibonacci(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def flatten(lst):
    result = []
    for item in lst:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def most_common(lst):
    """Return the element that appears most frequently in lst."""
    if not lst:
        return None
    counts = {}
    for item in lst:
        counts[item] = counts.get(item, 0) + 1
    max_count = -1
    most_common_item = None
    for item, count in counts.items():
        if count > max_count:
            max_count = count
            most_common_item = item
    return most_common_item

def merge_sorted(a, b):
    """Merge two sorted lists into a single sorted list."""
    i, j = 0, 0
    merged = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            merged.append(a[i])
            i += 1
        else:
            merged.append(b[j])
            j += 1
    # Append any remaining elements
    if i < len(a):
        merged.extend(a[i:])
    if j < len(b):
        merged.extend(b[j:])
    return merged

def is_valid_email(email):
    """Return True if email contains one '@' and a domain part with at least one dot."""
    try:
        local, domain = email.split('@')
    except ValueError:
        return False
    if not local or not domain:
        return False
    if '.' not in domain:
        return False
    # Basic check: no spaces and at least one character before and after dot
    parts = domain.split('.')
    if any(not part for part in parts):
        return False
    return True

